<?php
$terms=$pdo->query('SELECT id,academic_year,term_number,name,starts_on,ends_on FROM school_terms ORDER BY starts_on DESC')->fetchAll();
$selectedForm=filter_var($_GET['form']??null,FILTER_VALIDATE_INT);
$selectedTerm=filter_var($_GET['term_id']??null,FILTER_VALIDATE_INT);
$learners=[];
if ($selectedForm && $selectedForm>=1 && $selectedForm<=6) {
    $q=$pdo->prepare("SELECT s.id,s.admission_no,s.first_name,s.last_name,s.form_level,s.stream,e.id AS enrolment_id,e.start_date FROM students s JOIN student_enrolments e ON e.student_id=s.id AND e.end_date IS NULL WHERE s.status='Active' AND s.form_level=:form ORDER BY s.stream,s.last_name,s.first_name");
    $q->execute(['form'=>$selectedForm]); $learners=$q->fetchAll();
}
?>
<div class="page-heading"><div><div class="eyebrow">LEARNER RECORDS</div><h1>Class progression</h1><p class="subheading">Move a selected cohort into a configured school term while retaining each learner’s previous class history.</p></div><a class="outline-button" href="?page=students">← Learner directory</a></div>
<section class="panel info-panel academic-note"><h2>Before you progress a class</h2><p>Set up the destination term and each destination form/stream in Academics → Academic terms and Classes first. Confirm the term start date and review the selected learners before recording the move. Form 6 learners can be marked as completed instead of moved to another form.</p></section>
<?php if (!$terms): ?><section class="panel settings-panel"><h2>No school terms configured</h2><p>Create the next term under Academics → Academic terms, then return here.</p><a class="primary-button" href="?page=academics&tab=terms">Set up academic terms</a></section><?php else: ?>
<section class="panel settings-panel"><h2>Select source class</h2><form method="get" class="compact-form"><input type="hidden" name="page" value="students"><input type="hidden" name="progression" value="1"><label>Current form<select name="form" required><?php for($f=1;$f<=6;$f++): ?><option value="<?= $f ?>" <?= $selectedForm===$f?'selected':'' ?>>Form <?= $f ?></option><?php endfor; ?></select></label><label>Destination term<select name="term_id" required><option value="">Select term</option><?php foreach($terms as $term): ?><option value="<?= (int)$term['id'] ?>" <?= $selectedTerm===(int)$term['id']?'selected':'' ?>><?= h($term['name']) ?> · <?= (int)$term['academic_year'] ?> (<?= h(date('d M Y',strtotime($term['starts_on']))) ?>)</option><?php endforeach; ?></select></label><button class="primary-button">Show learners</button></form></section>
<?php if ($selectedForm && $selectedTerm && $selectedForm>=1 && $selectedForm<=6): $destination=null; foreach($terms as $t)if((int)$t['id']===$selectedTerm)$destination=$t; ?>
<?php if (!$destination): ?><div class="alert alert-error">Choose a configured destination term.</div><?php elseif (!$learners): ?><section class="panel settings-panel"><p>No active learners with an open enrollment record were found in Form <?= (int)$selectedForm ?>.</p></section><?php else: ?>
<section class="panel settings-panel"><h2>Review destination</h2><form method="post" action="actions/student_progress.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="term_id" value="<?= (int)$destination['id'] ?>"><input type="hidden" name="source_form" value="<?= (int)$selectedForm ?>"><label>New form<select name="target_form" required><?php for($f=1;$f<=6;$f++): ?><option value="<?= $f ?>" <?= $f===min($selectedForm+1,6)?'selected':'' ?>>Form <?= $f ?></option><?php endfor; ?><option value="completed">Complete Form 6 (no further enrollment)</option></select></label><label>New stream<input name="stream" maxlength="20" placeholder="Leave blank if not used"></label><label>Reason <span class="optional">Optional</span><input name="reason" maxlength="200" placeholder="e.g. Annual promotion"></label>
<div class="table-scroll"><table class="data-table"><thead><tr><th><input type="checkbox" id="selectAllProgression" checked aria-label="Select all learners"></th><th>Learner</th><th>Admission no.</th><th>Current class</th></tr></thead><tbody><?php foreach($learners as $l): ?><tr><td><input type="checkbox" name="student_ids[]" value="<?= (int)$l['id'] ?>" checked></td><td><?= h($l['first_name'].' '.$l['last_name']) ?></td><td><?= h($l['admission_no']) ?></td><td>Form <?= (int)$l['form_level'] ?><?= $l['stream']?' · '.h($l['stream']):'' ?></td></tr><?php endforeach; ?></tbody></table></div><div class="form-actions"><a class="outline-button" href="?page=students">Cancel</a><button class="primary-button" onclick="return confirm('Record progression for only the selected learners? Their previous enrollment records will be retained.')">Record progression</button></div></form></section>
<?php endif; ?><?php endif; ?><?php endif; ?>
<script>document.getElementById('selectAllProgression')?.addEventListener('change',function(){document.querySelectorAll('input[name="student_ids[]"]').forEach(x=>x.checked=this.checked)});</script>
